CREATE COLUMN TABLE "EXT"."WF_REPEXT_COEFICIENTES_REPARTO_FILE"(
	"ID_COEFICIENTES_REPARTO" BIGINT CS_FIXED NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1),
	"CIA_CODIGO" CHAR(2) CS_FIXEDSTRING NOT NULL,
	"TIPO_REPARTO" CHAR(3) CS_FIXEDSTRING NOT NULL,
	"PRODUCTO_DESDE" BIGINT CS_FIXED,
	"PRODUCTO_HASTA" BIGINT CS_FIXED,
	"COEF_CORRECTOR_TRAMO1" DECIMAL(5, 2) CS_FIXED,
	"TIPO_BASE_TRAMO1" CHAR(3) CS_FIXEDSTRING,
	"COEF_CORRECTOR_TRAMO2" DECIMAL(5, 2) CS_FIXED,
	"TIPO_BASE_TRAMO2" CHAR(3) CS_FIXEDSTRING,
	"FECHA_INICIO" VARCHAR(8),
	"FECHA_FIN" VARCHAR(8),
	"USUARIO" CHAR(10) CS_FIXEDSTRING,
	"FECHA_ALTA" LONGDATE CS_LONGDATE,
	"FECHA_BAJA" LONGDATE CS_LONGDATE
)
UNLOAD PRIORITY 5 AUTO MERGE;
